<div><label for="name">Nama</label><input class="field" id="name" name="name" value="{{ old('name', $record?->name) }}" maxlength="255" autocomplete="name" required></div>
<div><label for="email">Email</label><input class="field" id="email" name="email" type="email" value="{{ old('email', $record?->email) }}" maxlength="255" autocomplete="email" required></div>
<div><label for="password">Password {{ $record?->exists ? 'baru (opsional)' : '' }}</label><input class="field" id="password" name="password" type="password" autocomplete="new-password" minlength="12" aria-describedby="password-help" @required(! $record?->exists)><p id="password-help" class="mt-1 text-sm text-slate-600">Minimal 12 karakter. {{ $record?->exists ? 'Kosongkan untuk mempertahankan password lama.' : '' }}</p></div>
<div><label for="password_confirmation">Konfirmasi password</label><input class="field" id="password_confirmation" name="password_confirmation" type="password" autocomplete="new-password" @required(! $record?->exists)></div>
